import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('se-fiel-hasta-la-muerte', 'A',
 [dict(t=943, e=992, titulo='Hacer lo que Dios no mandó es infidelidad', txt='[…] cuando alguien es infiel, no está honrando a Dios. La Biblia dice que el que honra a Dios, Dios lo honra; pero Uzías no iba a recibir honra, ¿por qué? Porque estaba siendo infiel. Entonces, hermano, yo quiero dejar bien sentado este pensamiento: cuando nosotros hacemos algo que Dios no nos mandó a hacer, estamos siendo infieles delante de Dios. Yo tengo que saber a qué me mandó Dios a mí. Si Dios no me dijo que yo hiciera eso, no lo tengo que hacer. Si Dios no me mandó a ese lugar, yo no tengo que ir. Si Dios me dijo que dejara a Lot y no lo dejo, estoy siendo infiel.'),
  dict(t=2133, e=2166, titulo='Los que están con él son llamados, escogidos y fieles', txt='Bueno, ya le mostré algunos ejemplos de algunos personajes que fueron infieles en la Biblia, por lo menos tres. Y aquí, en Apocalipsis 17:14, dice: «Estos pelearán contra el Cordero, y el Cordero los vencerá, porque él es Señor de señores y Rey de reyes; y los que están con él son llamados, escogidos y fieles». Estamos con el Señor, pero hay tres niveles diferentes: como el atrio, el lugar santo y el lugar santísimo; como el treinta, el sesenta y el cien por ciento; como Marta, María y Lázaro […].'),
  dict(t=3783, e=3832, titulo='Fiel hasta la muerte y una vida en el espíritu', txt='Mire lo que significa. ¿Se acuerda de Apocalipsis 2:10? Decía que no temas lo que ha de venir, porque te van a meter a la cárcel. Aún sufrirás tribulación por diez días; pero sé fiel hasta la muerte, y yo te daré la corona de la vida. Mire esa vida: esa vida es la palabra zoé, es la vida en el espíritu, la de los vivientes. Nosotros, como hijos de Dios, no tenemos que vivir una vida en la carne, porque nos vamos a frustrar, no vamos a alcanzar nada, no nos vamos a deleitar en nada. Pero si tenemos una vida en el espíritu, vamos a deleitarnos en lo que hacemos.')],
 [dict(t=843, txt='Usted y yo tenemos límites de parte de Dios. A veces no nos gustan, pero los límites son para guardarnos y cuidarnos a nosotros.'),
  dict(t=1609, txt='Si no tenemos cuidado de nuestro hermano en Cristo, estamos siendo infieles.'),
  dict(t=3553, txt='Seamos fieles en lo poco para que nos den más.')],
 ['¿Hay algo que estás haciendo —o algún lugar al que vas— que Dios no te mandó? ¿Qué límite quiere ponerte hoy para cuidarte?',
  '¿A qué hermano más pequeño en la fe podrías cuidar esta semana, siendo fiel como alguien maduro?',
  '¿En qué «cosa pequeña» —o en algo que no es tuyo— el Señor te está probando para ver si eres digno de confianza?'])
